import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (n == -1) break;

            long oddSum = 0, evenSum = 0;
            for (int i = 0; i < n; i++) {
                int x = sc.nextInt();
                if ((x & 1) == 1) oddSum += x;
                else evenSum += x;
            }

            System.out.println(oddSum > evenSum ? "Odd Sum Greater" : "Even Sum Greater");
        }
        sc.close();
    }
}
